const express = require('express');
const path = require('path');
const fs = require('fs');
const crypto = require('crypto');
const argon2 = require('argon2');

const app = express();
const DOCS_ROOT = '/var/www/docs';
const UPLOAD_DIR = '/var/www/uploads';

// Session store
const sessions = new Map();

// Users with argon2 hashes
const users = new Map();
(async () => {
  users.set('admin', { role: 'admin', hash: await argon2.hash('Str0ng!Pass#2024') });
  users.set('viewer', { role: 'viewer', hash: await argon2.hash('V13w3r!Pass#2024') });
})();

// Generate session token
function generateSessionId() {
  return crypto.randomBytes(32).toString('hex');
}

// Auth middleware
function requireAuth(req, res, next) {
  const sid = req.headers['x-session-id'];
  if (!sid || typeof sid !== 'string') return res.status(401).json({ error: 'Unauthorized' });
  const session = sessions.get(sid);
  if (!session || session.expires < Date.now()) {
    sessions.delete(sid);
    return res.status(401).json({ error: 'Session expired' });
  }
  req.session = session;
  req.sessionId = sid;
  next();
}

// URL decode middleware - normalizes percent-encoded characters FIRST
// SECURITY: Decoding must happen BEFORE security checks to prevent
// double-encoding bypass attacks (CWE-22 via encoding layers)
function urlDecodeMiddleware(req, res, next) {
  const rawPath = req.params.filepath || req.params[0] || '';
  // Decode percent-encoded characters before any security validation
  try {
    req.decodedPath = decodeURIComponent(rawPath);
  } catch (e) {
    return res.status(400).json({ error: 'Invalid URL encoding' });
  }
  next();
}

// Path security middleware - validates DECODED path components
// SECURITY: This runs AFTER decoding to catch traversal in decoded form
function pathSecurityCheck(req, res, next) {
  const checkPath = req.decodedPath || '';

  // Block directory traversal sequences in decoded path
  if (checkPath.includes('..')) {
    return res.status(403).json({ error: 'Path traversal detected' });
  }

  // Block null bytes in decoded path
  if (checkPath.includes('\x00')) {
    return res.status(403).json({ error: 'Null byte detected' });
  }

  // Block absolute paths
  if (checkPath.startsWith('/')) {
    return res.status(403).json({ error: 'Absolute paths not allowed' });
  }

  // Additional: block backslash-based traversal (Windows compat)
  if (checkPath.includes('\\')) {
    return res.status(403).json({ error: 'Backslash not allowed' });
  }

  req.validatedPath = checkPath;
  next();
}

// Login endpoint
app.post('/api/auth/login', express.json(), async (req, res) => {
  const { username, password } = req.body;
  if (typeof username !== 'string' || typeof password !== 'string') {
    return res.status(400).json({ error: 'Invalid input' });
  }

  const user = users.get(username);
  if (!user) {
    // Timing-safe: still do argon2 work
    await argon2.hash(password);
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  try {
    if (await argon2.verify(user.hash, password)) {
      const sid = generateSessionId();
      sessions.set(sid, {
        userId: username,
        role: user.role,
        expires: Date.now() + 3600000,
        createdAt: Date.now()
      });
      return res.json({ sessionId: sid, role: user.role });
    }
  } catch (e) {
    // argon2 verify error
  }

  return res.status(401).json({ error: 'Invalid credentials' });
});

// File access endpoint - applies decode THEN security check
// SECURITY NOTE: Order matters! decode -> validate -> use
// This prevents double-encoding attacks where %2e%2e bypasses
// a check on the raw (still-encoded) string
app.get('/api/docs/*',
  requireAuth,
  urlDecodeMiddleware,
  pathSecurityCheck,
  (req, res) => {
    if (!req.validatedPath) {
      return res.status(400).json({ error: 'No path specified' });
    }

    const fullPath = path.join(DOCS_ROOT, req.validatedPath);

    // Defense in depth: verify resolved path is within DOCS_ROOT
    const resolved = path.resolve(fullPath);
    if (!resolved.startsWith(DOCS_ROOT)) {
      return res.status(403).json({ error: 'Access denied' });
    }

    fs.readFile(resolved, 'utf8', (err, data) => {
      if (err) {
        if (err.code === 'ENOENT') return res.status(404).json({ error: 'Not found' });
        return res.status(500).json({ error: 'Internal error' });
      }
      res.json({ content: data, path: req.validatedPath });
    });
  }
);

// File listing endpoint
app.get('/api/list/*',
  requireAuth,
  urlDecodeMiddleware,
  pathSecurityCheck,
  (req, res) => {
    const dirPath = req.validatedPath || '';
    const fullPath = path.join(DOCS_ROOT, dirPath);
    const resolved = path.resolve(fullPath);

    if (!resolved.startsWith(DOCS_ROOT)) {
      return res.status(403).json({ error: 'Access denied' });
    }

    fs.readdir(resolved, { withFileTypes: true }, (err, entries) => {
      if (err) return res.status(404).json({ error: 'Directory not found' });
      const items = entries.map(e => ({
        name: e.name,
        type: e.isDirectory() ? 'dir' : 'file'
      }));
      res.json({ items, path: dirPath });
    });
  }
);

// Logout
app.post('/api/auth/logout', requireAuth, (req, res) => {
  sessions.delete(req.sessionId);
  res.json({ success: true });
});

app.listen(3000, '127.0.0.1');
module.exports = app;
